// Some portions generated by Claude
/**
 * A force layout's orientation is arbitrary. Organize turns the drawing so it fills the viewport, then picks the mirror
 * image (left–right, top–bottom or both) closest to what was on screen, so organizing again does not flip the map.
 */
import { graphNodeSize } from './graph-geometry.ts';
import { separateLayoutRectangles } from './graph-layout-overlap.ts';
import { layoutScoreGeometry } from './graph-layout-score.ts';
import { measureLayoutConflicts } from './graph-layout.ts';
import type { Graph, PointerPosition } from './graph-types.ts';
import type { LayoutOptions } from './graph-layout-engine.ts';

/** A turn must make the drawing fill this much more of the viewport to be worth re-separating the cards. */
const TURN_GAIN = 1.08;

function centroid(points: Iterable<PointerPosition>) {
  let x = 0, y = 0, n = 0;
  for (const p of points) {x += p.x; y += p.y; n++;}
  return n ? {x: x / n, y: y / n} : {x: 0, y: 0};
}

/** Fraction of a viewport with this width/height ratio that the fitted drawing fills. */
function viewportFill(graph: Graph, positions: Map<string, PointerPosition>, aspect: number) {
  let minX = Infinity, maxX = -Infinity, minY = Infinity, maxY = -Infinity;
  for (const node of graph.nodes) {
    const p = positions.get(node.id);
    if (!p) continue;
    const size = graphNodeSize(node);
    minX = Math.min(minX, p.x - size.width / 2); maxX = Math.max(maxX, p.x + size.width / 2);
    minY = Math.min(minY, p.y - size.height / 2); maxY = Math.max(maxY, p.y + size.height / 2);
  }
  const width = Math.max(1, maxX - minX), height = Math.max(1, maxY - minY);
  const scale = Math.min(aspect / width, 1 / height);
  return (width * scale * height * scale) / aspect;
}

function rotated(positions: Map<string, PointerPosition>, angle: number) {
  const c = centroid(positions.values()), cos = Math.cos(angle), sin = Math.sin(angle);
  return new Map([...positions].map(([id, p]) => [id, {x: c.x + (p.x - c.x) * cos - (p.y - c.y) * sin, y: c.y + (p.x - c.x) * sin + (p.y - c.y) * cos}]));
}

const conflicts = (graph: Graph, positions: Map<string, PointerPosition>, options: LayoutOptions) => {
  const g = layoutScoreGeometry(graph, positions, options), m = measureLayoutConflicts(g.nodes, g.edges);
  return m.edgeCrossings + m.edgeNodeOverlaps;
};

/**
 * Turns the drawing so its long axis follows the viewport's, when that fills the viewport noticeably better and the
 * cards, separated again after the turn, have no more crossings or edges through cards. Named group boxes are
 * axis-aligned and stay as they are.
 */
export function orientToViewport(graph: Graph, positions: Map<string, PointerPosition>, options: LayoutOptions) {
  if (graph.nodes.length < 3 || options.groups?.length) return;
  const aspect = Math.max(0.2, Math.min(5, options.aspectRatio ?? 1.6));
  const c = centroid(positions.values());
  let xx = 0, yy = 0, xy = 0;
  for (const p of positions.values()) {xx += (p.x - c.x) ** 2; yy += (p.y - c.y) ** 2; xy += (p.x - c.x) * (p.y - c.y);}
  const axis = 0.5 * Math.atan2(2 * xy, xx - yy);
  let best = positions, bestFill = viewportFill(graph, positions, aspect) * TURN_GAIN;
  for (const angle of [-axis, Math.PI / 2 - axis]) {
    if (Math.abs(Math.sin(angle)) < 0.02) continue;
    const candidate = rotated(positions, angle);
    const fill = viewportFill(graph, candidate, aspect);
    if (fill > bestFill) {best = candidate; bestFill = fill;}
  }
  if (best === positions) return;
  separateLayoutRectangles(graph, best, options);
  if (conflicts(graph, best, options) > conflicts(graph, positions, options)) return;
  best.forEach((p, id) => positions.set(id, p));
}

/**
 * Picks, among the drawing and its three mirror images (which keep every card's clearance), the one closest to the
 * positions the cards had before, and centres it where they were.
 */
export function keepPreviousOrientation(graph: Graph, positions: Map<string, PointerPosition>) {
  const previous = new Map(graph.nodes.flatMap(node => (Number.isFinite(node.x) && Number.isFinite(node.y) && positions.has(node.id) ? [[node.id, {x: node.x!, y: node.y!}]] : [])));
  if (previous.size < 2) return;
  const before = centroid(previous.values()), now = centroid([...previous.keys()].map(id => positions.get(id)!));
  const spread = [...previous.values()].reduce((sum, p) => sum + Math.abs(p.x - before.x) + Math.abs(p.y - before.y), 0);
  if (spread < 1) return;
  let best = {sx: 1, sy: 1}, bestCost = Infinity;
  for (const [sx, sy] of [[1, 1], [-1, 1], [1, -1], [-1, -1]]) {
    let cost = 0;
    for (const [id, p] of previous) {
      const q = positions.get(id)!;
      cost += (now.x + (q.x - now.x) * sx - now.x - (p.x - before.x)) ** 2 + (now.y + (q.y - now.y) * sy - now.y - (p.y - before.y)) ** 2;
    }
    if (cost < bestCost - 1e-6) {bestCost = cost; best = {sx, sy};}
  }
  positions.forEach((q, id) => positions.set(id, {x: before.x + (q.x - now.x) * best.sx, y: before.y + (q.y - now.y) * best.sy}));
}
